http_snippet:
# Public listing responses contain no user-specific data. Leave credentials/cookies uncompressed.
map "$request_method:$host:$uri:$http_authorization:$http_cookie" $registry_public_json_gzip {
    default 0;
    ~^(GET|HEAD):(registry\.modelcontextprotocol\.io|prod\.registry\.modelcontextprotocol\.io|staging\.registry\.modelcontextprotocol\.io):/v0(?:\.1)?/servers::$ 1;
}

location_snippet:
# Compress the public JSON representation after cache lookup; preserve identity fallback.
gzip off;
gzip_types application/json;
gzip_min_length 1024;
gzip_comp_level 1;
gzip_proxied any;
gzip_vary on;
if ($registry_public_json_gzip) {
    gzip on;
}
